    const { data: notebook, error: nbErr } = await client.from("notebooks").insert({
      owner_id: userId,
      title,
      subject,
      subtopic,
      class_name: className,
      teacher
    }).select("id").single();
    if (nbErr || !notebook)
      return err(nbErr?.message ?? "Could not create the notebook.");
    let sectionCount = 0;
